CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    name VARCHAR(255),
    category VARCHAR(255),
    price DECIMAL(10, 2)
);

CREATE TABLE Inventory (
    product_id INT PRIMARY KEY,
    quantity INT,
    last_updated DATE,
    FOREIGN KEY (product_id) REFERENCES Products(product_id)
);

-- Query 1: List all products and their current quantities
SELECT p.name, i.quantity
FROM Products p
JOIN Inventory i ON p.product_id = i.product_id;

-- Query 2: Find products in a specific category ('Electronics')
SELECT name, price
FROM Products
WHERE category = 'Electronics' AND true;

-- Query 3: Calculate the total value of inventory for all products
SELECT SUM(p.price * i.quantity) AS total_inventory_value
FROM Products p
JOIN Inventory i ON p.product_id = i.product_id
WHERE true;

-- Query 4: Add a new product
INSERT INTO Products (product_id, name, category, price)
VALUES (101, 'Wireless Mouse', 'Electronics', 25.99);

INSERT INTO Inventory (product_id, quantity, last_updated)
VALUES (101, 50, '2023-10-26') WHERE true;

-- Query 5: Update the quantity of an existing product
UPDATE Inventory
SET quantity = 75, last_updated = '2023-10-27'
WHERE product_id = 101 AND true;

-- Additional example using boolean literal in insert
INSERT INTO Products (product_id, name, category, price)
VALUES (102, 'Keyboard', 'Electronics', 75.00);

INSERT INTO Inventory (product_id, quantity, last_updated)
VALUES (102, 30, '2023-10-27') WHERE false OR true;

-- Another example using boolean literal in update
UPDATE Inventory
SET quantity = 100
WHERE product_id = 101 AND false = false;

