-- 1. List all 'In Progress' modules for 'User A' in 'Introduction to SQL'.
SELECT M.ModuleName
FROM Progress P
JOIN Enrollments E ON P.EnrollmentID = E.EnrollmentID
JOIN Courses C ON E.CourseID = C.CourseID
JOIN Modules M ON P.ModuleID = M.ModuleID
WHERE E.UserID = 1001 AND C.CourseName = 'Introduction to SQL' AND P.CompletionStatus = 'In Progress';

-- 2. Calculate the percentage of modules completed by each user in a specific course.
SELECT E.UserID, CAST(SUM(CASE WHEN P.CompletionStatus = 'Completed' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(M.ModuleID) AS CompletionPercentage
FROM Enrollments E
JOIN Modules M ON E.CourseID = M.CourseID
LEFT JOIN Progress P ON E.EnrollmentID = P.EnrollmentID AND M.ModuleID = P.ModuleID
WHERE E.CourseID = 1
GROUP BY E.UserID;

-- 3. Find courses where all enrolled students have completed at least 50% of the modules.
SELECT C.CourseName
FROM Courses C
WHERE true = ALL (
    SELECT (CAST(SUM(CASE WHEN P.CompletionStatus = 'Completed' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(M.ModuleID)) >= 50
    FROM Enrollments E
    JOIN Modules M ON E.CourseID = M.CourseID
    LEFT JOIN Progress P ON E.EnrollmentID = P.EnrollmentID AND M.ModuleID = P.ModuleID
    WHERE E.CourseID = C.CourseID
    GROUP BY E.UserID
) AND true;

