    episode_id INT,
    guest_id INT,
    is_main_guest BOOLEAN,
    PRIMARY KEY (episode_id, guest_id),
    FOREIGN KEY (episode_id) REFERENCES Episodes(episode_id),
    FOREIGN KEY (guest_id) REFERENCES Guests(guest_id)
);

