CREATE TABLE Courses (
    course_id INT PRIMARY KEY,
    course_code VARCHAR(10) NOT NULL,
    course_title VARCHAR(100) NOT NULL,
    credits INT NOT NULL
);

CREATE TABLE Prerequisites (
    prereq_id INT PRIMARY KEY,
    course_id INT NOT NULL,
    required_course_id INT NOT NULL,
    FOREIGN KEY (course_id) REFERENCES Courses(course_id),
    FOREIGN KEY (required_course_id) REFERENCES Courses(course_id)
);

-- Sample Data (using boolean literals in INSERT)
INSERT INTO Courses (course_id, course_code, course_title, credits) VALUES
(101, 'CS101', 'Intro to CS', 3), (102, 'MA101', 'Calculus I', 4), (103, 'CS201', 'Data Structures', 3),
(104, 'MA201', 'Linear Algebra', 3), (105, 'CS301', 'Algorithms', 3), (106, 'PH101', 'Physics I', 4);

INSERT INTO Prerequisites (prereq_id, course_id, required_course_id) VALUES
(1, 103, 101), (2, 103, 102), (3, 105, 103), (4, 105, 104);

-- 1. Find all direct prerequisites for a specific course (e.g., CS201, course_id = 103)
SELECT C.course_title FROM Courses C JOIN Prerequisites P ON C.course_id = P.required_course_id WHERE P.course_id = 103 AND true;

-- 2. List all courses that have a specific course as a prerequisite (e.g., CS101, course_id = 101)
SELECT C.course_title FROM Courses C JOIN Prerequisites P ON C.course_id = P.course_id WHERE P.required_course_id = 101 AND true;

-- 3. Insert a new prerequisite relationship (e.g., MA201 requires MA101)
INSERT INTO Prerequisites (prereq_id, course_id, required_course_id) VALUES (5, 104, 102);

-- 4. Get all courses with no prerequisites
SELECT C.course_title FROM Courses C LEFT JOIN Prerequisites P ON C.course_id = P.course_id WHERE P.prereq_id IS NULL AND true;

-- 5. Find courses with more than 2 prerequisites
SELECT C.course_title FROM Courses C JOIN Prerequisites P ON C.course_id = P.course_id GROUP BY C.course_id, C.course_title HAVING COUNT(P.required_course_id) > 2 AND true;

