CREATE TABLE Projects (
    project_id INT PRIMARY KEY,
    project_name VARCHAR(255),
    start_date DATE,
    end_date DATE
);

CREATE TABLE Tasks (
    task_id INT PRIMARY KEY,
    project_id INT,
    task_name VARCHAR(255),
    due_date DATE,
    status VARCHAR(50),
    FOREIGN KEY (project_id) REFERENCES Projects(project_id)
);

CREATE TABLE TaskDependencies (
    task_id INT,
    depends_on_task_id INT,
    PRIMARY KEY (task_id, depends_on_task_id),
    FOREIGN KEY (task_id) REFERENCES Tasks(task_id),
    FOREIGN KEY (depends_on_task_id) REFERENCES Tasks(task_id)
);

-- Sample Data
INSERT INTO Projects VALUES (1, 'Website Redesign', '2023-01-01', '2023-03-31');
INSERT INTO Projects VALUES (2, 'Mobile App Dev', '2023-02-15', '2023-06-30');

INSERT INTO Tasks VALUES (101, 1, 'Design Mockups', '2023-01-15', 'completed');
INSERT INTO Tasks VALUES (102, 1, 'Develop Frontend', '2023-02-15', 'pending');
INSERT INTO Tasks VALUES (103, 1, 'Develop Backend', '2023-02-28', 'pending');
INSERT INTO Tasks VALUES (104, 1, 'Deploy Website', '2023-03-15', 'pending');
INSERT INTO Tasks VALUES (201, 2, 'Plan Features', '2023-02-20', 'completed');
INSERT INTO Tasks VALUES (202, 2, 'Develop iOS App', '2023-04-30', 'pending');
INSERT INTO Tasks VALUES (203, 2, 'Develop Android App', '2023-05-15', 'pending');

INSERT INTO TaskDependencies VALUES (102, 101);
INSERT INTO TaskDependencies VALUES (103, 101);
INSERT INTO TaskDependencies VALUES (104, 102);
INSERT INTO TaskDependencies VALUES (104, 103);
INSERT INTO TaskDependencies VALUES (202, 201);
INSERT INTO TaskDependencies VALUES (203, 201);

-- Queries
-- 1. List all tasks for a specific project (e.g., project_id = 1)
SELECT * FROM Tasks WHERE project_id = 1;

-- 2. Find all tasks that a specific task (e.g., task_id = 104) depends on
SELECT T.* FROM Tasks T JOIN TaskDependencies TD ON T.task_id = TD.depends_on_task_id WHERE TD.task_id = 104;

-- 3. Insert a new task dependency (e.g., task 103 depends on task 102)
INSERT INTO TaskDependencies VALUES (103, 102);

-- 4. Find tasks that are 'pending' but have all their dependencies 'completed'
SELECT T.task_id, T.task_name
FROM Tasks T
WHERE T.status = 'pending'
  AND (NOT EXISTS (SELECT 1 FROM TaskDependencies TD WHERE TD.task_id = T.task_id) OR
       NOT EXISTS (SELECT 1 FROM TaskDependencies TD JOIN Tasks DepT ON TD.depends_on_task_id = DepT.task_id
                   WHERE TD.task_id = T.task_id AND DepT.status != 'completed')); -- false for incomplete

-- 5. Get the count of dependencies for each task
SELECT T.task_id, T.task_name, COUNT(TD.depends_on_task_id) AS dependency_count
FROM Tasks T
LEFT JOIN TaskDependencies TD ON T.task_id = TD.task_id
GROUP BY T.task_id, T.task_name;

-- Additional example using boolean literal
UPDATE Tasks SET status = 'completed' WHERE task_id = 102 AND true;

-- Another example
SELECT project_id, project_name FROM Projects WHERE start_date < CURRENT_DATE AND true;

-- Final example
DELETE FROM TaskDependencies WHERE task_id = 103 AND depends_on_task_id = 102 AND true;

