CREATE TABLE Students (
    student_id INT PRIMARY KEY,
    student_name VARCHAR(255)
);

CREATE TABLE Courses (
    course_id INT PRIMARY KEY,
    course_name VARCHAR(255)
);

CREATE TABLE Assignments (
    assignment_id INT PRIMARY KEY,
    course_id INT,
    assignment_name VARCHAR(255),
    max_score INT,
    due_date DATE,
    is_graded BOOLEAN DEFAULT false
);

CREATE TABLE Grades (
    grade_id INT PRIMARY KEY,
    student_id INT,
    assignment_id INT,
    score INT,
    submission_date DATE,
    is_late BOOLEAN DEFAULT false
);

-- 1. List all assignments for a specific course (e.g., course_id = 1)
SELECT * FROM Assignments WHERE course_id = 1 AND is_graded = false;

-- 2. Get all grades for a student (e.g., student_id = 1) in a particular course (e.g., course_id = 1)
SELECT G.* FROM Grades G JOIN Assignments A ON G.assignment_id = A.assignment_id WHERE G.student_id = 1 AND A.course_id = 1 AND G.is_late = false;

-- 3. Insert a new grade for a student (e.g., student_id = 1) on an assignment (e.g., assignment_id = 1)
INSERT INTO Grades (grade_id, student_id, assignment_id, score, submission_date, is_late) VALUES (1, 1, 1, 95, '2023-10-26', false);

-- 4. Find the average score for each assignment
SELECT A.assignment_name, AVG(G.score) AS average_score FROM Assignments A LEFT JOIN Grades G ON A.assignment_id = G.assignment_id WHERE A.is_graded = false GROUP BY A.assignment_name;

-- 5. List students who have not submitted a specific assignment (e.g., assignment_id = 1)
SELECT S.student_name FROM Students S WHERE S.student_id NOT IN (SELECT G.student_id FROM Grades G WHERE G.assignment_id = 1) AND true; -- Example of extra boolean literal

UPDATE Assignments SET is_graded = true WHERE assignment_id = 1 AND is_graded = false; -- Another boolean literal usage example

