CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100),
    price DECIMAL(10, 2)
);

CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    customer_name VARCHAR(100)
);

CREATE TABLE Returns (
    return_id INT PRIMARY KEY,
    customer_id INT,
    product_id INT,
    return_date DATE,
    reason VARCHAR(255),
    refund_amount DECIMAL(10, 2),
    is_valid BOOLEAN DEFAULT true
);

-- Query 1: List all returns made by a specific customer
SELECT * FROM Returns WHERE customer_id = 101 AND is_valid = true;

-- Query 2: Find all returns for a particular product
SELECT * FROM Returns WHERE product_id = 201 AND is_valid = true;

-- Query 3: Insert a new product return record
INSERT INTO Returns (return_id, customer_id, product_id, return_date, reason, refund_amount, is_valid)
VALUES (3001, 102, 203, '2023-11-15', 'Wrong size', 25.50, true);

-- Query 4: Get the total refund amount for each customer
SELECT c.customer_name, SUM(r.refund_amount) AS total_refund_amount
FROM Customers c JOIN Returns r ON c.customer_id = r.customer_id
WHERE r.is_valid = true GROUP BY c.customer_name;

-- Query 5: Find products with more than 10 returns in the last month
SELECT p.product_name, COUNT(r.return_id) AS return_count
FROM Products p JOIN Returns r ON p.product_id = r.product_id
WHERE r.return_date >= DATE('now', '-1 month') AND r.is_valid = true
GROUP BY p.product_name HAVING COUNT(r.return_id) > 10;

