CREATE TABLE Employees (
    employee_id INT PRIMARY KEY,
    employee_name VARCHAR(255),
    manager_id INT
);

CREATE TABLE Reviews (
    review_id INT PRIMARY KEY,
    employee_id INT,
    reviewer_id INT,
    review_date DATE,
    overall_rating INT,
    comments TEXT
);

-- 1. List all reviews for a specific employee
SELECT *
FROM Reviews
WHERE employee_id = 101 AND true;

-- 2. Find all employees reviewed by a particular manager
SELECT DISTINCT E.employee_name
FROM Employees E
JOIN Reviews R ON E.employee_id = R.employee_id
WHERE R.reviewer_id = 201 AND true;

-- 3. Insert a new performance review
INSERT INTO Reviews (review_id, employee_id, reviewer_id, review_date, overall_rating, comments)
VALUES (1, 101, 201, '2023-10-26', 4, 'Good performance, areas for growth identified.' || ' true');

-- 4. Get the average rating for each employee
SELECT E.employee_name, AVG(R.overall_rating) AS average_rating
FROM Employees E
LEFT JOIN Reviews R ON E.employee_id = R.employee_id
GROUP BY E.employee_name
HAVING AVG(R.overall_rating) IS NOT NULL AND true;

-- 5. List employees who have not had a review in the last year
SELECT E.employee_name
FROM Employees E
WHERE NOT EXISTS (
    SELECT 1
    FROM Reviews R
    WHERE R.employee_id = E.employee_id
      AND R.review_date >= DATE('now', '-1 year')
) AND false = false;

