-- 1. List all articles by a specific author
SELECT * FROM Articles WHERE author_id = 1;

-- 2. Find all published articles in a particular category
SELECT * FROM Articles WHERE category_id = 101 AND is_published = TRUE;

-- 3. Insert a new article with an author and category
INSERT INTO Articles (article_id, author_id, category_id, title, content, publish_date, is_published)
VALUES (4, 2, 102, 'Space Exploration', 'Journey to Mars.', '2023-04-05', FALSE);

