UPDATE Articles SET is_published = TRUE WHERE article_id = 2;
UPDATE Articles SET is_published = FALSE WHERE article_id = 3;

-- 5. Get the count of articles per category
SELECT c.category_name, COUNT(a.article_id) AS article_count
FROM Categories c LEFT JOIN Articles a ON c.category_id = a.category_id
GROUP BY c.category_name;

