    type_id INT PRIMARY KEY,
    type_name VARCHAR(255)
);

CREATE TABLE TimeOffRequests (
    request_id INT PRIMARY KEY,
    employee_id INT,
    type_id INT,
    start_date DATE,
    end_date DATE,
    status VARCHAR(50),
    approved_by_manager_id INT,
    is_approved BOOLEAN DEFAULT false
);

