CREATE TABLE Shipments (
    shipment_id INT PRIMARY KEY,
    order_id INT,
    carrier_name VARCHAR(50),
    tracking_number VARCHAR(100),
    shipment_date DATE,
    delivery_date DATE,
    status VARCHAR(50)
);

