CREATE TABLE Concerts (
    concert_id INT PRIMARY KEY,
    artist VARCHAR(255),
    venue VARCHAR(255),
    concert_date DATETIME,
    ticket_price DECIMAL(10, 2)
);

CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    name VARCHAR(255),
    email VARCHAR(255)
);

CREATE TABLE Tickets (
    ticket_id INT PRIMARY KEY,
    concert_id INT,
    customer_id INT,
    purchase_date DATETIME,
    is_refunded BOOLEAN DEFAULT false,
    FOREIGN KEY (concert_id) REFERENCES Concerts(concert_id),
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

-- Sample Data (for demonstration, includes boolean literals)
INSERT INTO Concerts (concert_id, artist, venue, concert_date, ticket_price) VALUES
(1, 'Artist A', 'Venue X', '2023-10-26 19:00:00', 50.00),
(2, 'Artist B', 'Venue Y', '2023-11-15 20:00:00', 75.50);

INSERT INTO Customers (customer_id, name, email) VALUES
(101, 'Alice', 'alice@example.com'),
