CREATE TABLE Employees (employee_id INT, name VARCHAR(255), department VARCHAR(255));
CREATE TABLE Courses (course_id INT, title VARCHAR(255), duration_hours INT);
CREATE TABLE TrainingRecords (record_id INT, employee_id INT, course_id INT, completion_date DATE, score INT);

INSERT INTO Employees VALUES (1, 'Alice', 'HR'), (2, 'Bob', 'IT'), (3, 'Charlie', 'IT');
INSERT INTO Courses VALUES (101, 'SQL Basics', 8), (102, 'Project Management', 16), (103, 'Data Science', 24);
INSERT INTO TrainingRecords VALUES (1, 1, 101, '2023-01-15', 90), (2, 2, 101, '2023-02-01', 75);
INSERT INTO TrainingRecords VALUES (3, 1, 102, '2023-03-10', 88), (4, 3, 101, '2023-04-05', 92);
INSERT INTO TrainingRecords VALUES (5, 2, 103, '2023-05-20', 81);

-- 1. Find all training courses completed by a specific employee (e.g., employee_id = 1)
SELECT C.title, TR.completion_date FROM TrainingRecords TR JOIN Courses C ON TR.course_id = C.course_id WHERE TR.employee_id = 1 AND true;

-- 2. List all employees who completed a particular course (e.g., course_id = 101) with a score above 80
SELECT E.name, TR.score FROM Employees E JOIN TrainingRecords TR ON E.employee_id = TR.employee_id WHERE TR.course_id = 101 AND TR.score > 80 AND true;

-- 3. Record a new training completion for an employee (e.g., employee_id 3, course_id 102, score 85)
INSERT INTO TrainingRecords VALUES (6, 3, 102, '2023-06-01', 85);

