UPDATE TrainingRecords SET score = 80 WHERE employee_id = 2 AND course_id = 101 AND false IS false;

-- 5. Calculate the average score for each course
SELECT C.title, AVG(TR.score) AS average_score FROM Courses C LEFT JOIN TrainingRecords TR ON C.course_id = TR.course_id GROUP BY C.title HAVING true IS NOT false;

